diff --git a/repro/repro.js b/repro/repro.js
new file mode 100644
index 000000000..54872e24a
--- /dev/null
+++ b/repro/repro.js
@@ -0,0 +1,19 @@
+// Usage: node repro/repro.js [path-to-typescript-module]   (default: built/local/typescript.js)
+const path = require("path");
+const ts = require(process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "../built/local/typescript.js"));
+const file = path.join(__dirname, "repro.ts");
+const program = ts.createProgram([file], { strict: true, noEmit: true });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+console.log("TypeScript", ts.version);
+let failed = false;
+for (const s of sf.statements) {
+    if (!ts.isTypeAliasDeclaration(s)) continue;
+    const name = s.name.text;
+    if (name !== "Test" && name !== "Test2") continue;
+    const printed = checker.typeToString(checker.getTypeAtLocation(s.name), undefined, ts.TypeFormatFlags.InTypeAlias);
+    console.log(`  ${name} = ${printed}`);
+    if (name === "Test" && printed !== '{ prop1: "hello"; }') failed = true;
+}
+console.log(failed ? 'BUG: Test should print as { prop1: "hello"; }' : "OK");
+process.exitCode = failed ? 1 : 0;
diff --git a/repro/repro.ts b/repro/repro.ts
new file mode 100644
index 000000000..ce3f5da15
--- /dev/null
+++ b/repro/repro.ts
@@ -0,0 +1,22 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+type Test2 = Unwrap<typeof value>["prop1"]
